  const culprits = [
    "mailer.ts in sendDigest",
    "billing.ts in chargeCard",
    "export.ts in writeCsv",
    "cleanup.ts in purgeOld",
  ];
  const out: any = {};
  for (const c of culprits) {
    const r = await sdk.linear.searchIssues({ query: c });
    out[c] = r.issues;
  }
  // also search broader terms
  for (const q of ["sendDigest", "chargeCard", "writeCsv", "purgeOld", "mailer.ts", "billing.ts", "export.ts", "cleanup.ts"]) {
    const r = await sdk.linear.searchIssues({ query: q });
    out["q:" + q] = r.issues.map(i => ({ identifier: i.identifier, title: i.title, description: i.description }));
  }
  return out;
}"}

