{"code": "export async function main(input: any) {
  const out: any = {};
  const targets = [
    { id: "4701", file: "src/jobs/mailer.ts", line: 31 },
    { id: "4702", file: "src/jobs/billing.ts", line: 77 },
    { id: "4703", file: "src/jobs/export.ts", line: 12 },
