  ];
  for (const t of targets) {
    const b = await sdk.github.getBlame({ file: t.file, line: t.line });
    const ev = await sdk.sentry.listIssueEvents({ issueId: t.id });
    out[t.id] = { blame: b, eventCount: ev.events.length };
