}"}

{"code": "export async function main(input: any) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const checked = issues.length;
  const qualifying = issues.filter(i => i.status === "unresolved" && i.count >= 150);

  const created: any[] = [];
  const plan: any[] = [];
  const seenCulprits = new Set<string>();

  for (const issue of qualifying) {
    if (seenCulprits.has(issue.culprit)) continue;
    const found = await sdk.linear.searchIssues({ query: issue.culprit });
    if (found.issues.length > 0) continue;
    seenCulprits.add(issue.culprit);
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    plan.push({ shortId: issue.shortId, culprit: issue.culprit, author: blame.authorEmail });
  }

  for (const p of plan) {
    const r = await sdk.linear.createIssue({
      title: "[Sentry] " + p.shortId,
      description: p.culprit,
      assigneeEmail: p.author,
    });
    created.push(r);
  }

  return { checked, plan, created };
}"}

